package io.github.polestarcn.companion;
import static org.junit.Assert.*;import org.junit.Test;import java.util.*;
public class LockReadbackV096Test {
 static class Clock implements CommandReadback.Scheduler {long now;int seq;static class Task{long at;int seq;Runnable r;}PriorityQueue<Task> tasks=new PriorityQueue<>((a,b)->a.at==b.at?a.seq-b.seq:Long.compare(a.at,b.at));public void after(long delay,Runnable r){Task t=new Task();t.at=now+delay;t.seq=seq++;t.r=r;tasks.add(t);}void to(long at){while(!tasks.isEmpty()&&tasks.peek().at<=at){Task t=tasks.remove();now=t.at;t.r.run();}now=at;}}
 VehicleSnapshot state(String lock){return new VehicleSnapshot("fixture","masked",60,200,1000,"空闲","全部关闭","全部关闭","已关闭",lock,1,"LIVE",false,"关闭","关闭");}
 @Test public void eachDirectionReadsAtThreeFiveSevenFifteenAndRetriesOnceAtSeven(){for(String action:new String[]{"lock","unlock"}){Clock c=new Clock();List<Long> reads=new ArrayList<>(),writes=new ArrayList<>();List<String> directions=new ArrayList<>();boolean[] sent={false},confirmed={false};new CommandReadback(()->{reads.add(c.now);return state(sent[0]?(action.equals("lock")?"已上锁":"未锁"):(action.equals("lock")?"未锁":"已上锁"));},Runnable::run,c,(s,ok)->confirmed[0]=ok).retryLockOnce(()->{writes.add(c.now);directions.add(action);sent[0]=true;},Runnable::run,()->true).start(action);c.to(6000);assertTrue(writes.isEmpty());c.to(7000);assertEquals(Arrays.asList(7000L),writes);c.to(50000);assertEquals(Arrays.asList(3000L,5000L,7000L,15000L),reads);assertEquals(Collections.singletonList(action),directions);assertTrue(confirmed[0]);}}
 @Test public void confirmationAtAnyEarlyCheckpointSkipsRetryAndAllLaterReads(){for(int match=1;match<=3;match++){Clock c=new Clock();int target=match;int[] reads={0},writes={0},done={0};new CommandReadback(()->state(++reads[0]>=target?"未锁":"已上锁"),Runnable::run,c,(s,ok)->{assertTrue(ok);done[0]++;}).retryLockOnce(()->writes[0]++,Runnable::run,()->true).start("unlock");c.to(30000);assertEquals(target,reads[0]);assertEquals(0,writes[0]);assertEquals(1,done[0]);}}
 @Test public void cancellationOrLogoutGuardStopsQueuedRetryAndFailureNeverRetriesTwice(){Clock c=new Clock();List<Runnable> worker=new ArrayList<>();int[] writes={0};CommandReadback r=new CommandReadback(()->state("已上锁"),Runnable::run,c,(s,ok)->assertFalse(ok)).retryLockOnce(()->writes[0]++,worker::add,()->true);r.start("unlock");c.to(7000);assertEquals(1,worker.size());r.cancel();worker.get(0).run();assertEquals(0,writes[0]);c.to(30000);Clock other=new Clock();new CommandReadback(()->null,Runnable::run,other,(s,ok)->assertFalse(ok)).retryLockOnce(()->writes[0]++,Runnable::run,()->false).start("lock");other.to(40000);assertEquals(0,writes[0]);}
}
